Here's a small, self-contained example: a note-taking CLI that saves notes to a JSON file.

```python
import json
import sys
from pathlib import Path

NOTES_FILE = Path("notes.json")

def load_notes():
    if NOTES_FILE.exists():
        return json.loads(NOTES_FILE.read_text())
    return []

def save_notes(notes):
    NOTES_FILE.write_text(json.dumps(notes, indent=2))

def add(note):
    notes = load_notes()
    notes.append(note)
    save_notes(notes)
    print(f"Added: {note}")

def list_notes():
    notes = load_notes()
    if not notes:
        print("No notes yet.")
        return
    for i, note in enumerate(notes, 1):
        print(f"{i}. {note}")

def main():
    if len(sys.argv) < 2:
        print("Usage: notes [add <text> | list]")
        return
    cmd = sys.argv[1]
    if cmd == "add" and len(sys.argv) > 2:
        add(" ".join(sys.argv[2:]))
    elif cmd == "list":
        list_notes()
    else:
        print("Unknown command.")

if __name__ == "__main__":
    main()
```

